{"sql":"SELECT t.TrackId, t.Name, cnt.playlist_count
FROM Track t
JOIN (
  SELECT TrackId, COUNT(DISTINCT PlaylistId) AS playlist_count
  FROM PlaylistTrack
  GROUP BY TrackId
) cnt USING (TrackId)
